function process(order: Order) {
  const tax = calculateTax(order);
  if (order.type === 'online') {
    const total = order.subtotal + tax;
    notifyUser(order.userId, total);
  } else {
    const total = order.subtotal + tax;
    printReceipt(order.id, total);
  }
}

function finalizeInvoice(invoice: Invoice) {
  const tax = computeTax(invoice);
  if (invoice.isPaid) {
    const total = invoice.subtotal + tax;
    sendPaidNotification(invoice.customerId, total);
  } else {
    const total = invoice.subtotal + tax;
    queueInvoiceForPayment(invoice.id, total);
  }
}

// Version A: small helper
function computeTotal(order: Order) {
  const tax = calculateTax(order);
  return order.subtotal + tax;
}

function processOrderA(order: Order) {
  const total = computeTotal(order);
  if (order.type === 'online') notifyUser(order.userId, total);
  else printReceipt(order.id, total);
}

// Version B: duplicated calculation in branches
function processOrderB(order: Order) {
  if (order.type === 'online') {
    const tax = calculateTax(order);
    const total = order.subtotal + tax;
    notifyUser(order.userId, total);
  } else {
    const tax = calculateTax(order);
    const total = order.subtotal + tax;
    printReceipt(order.id, total);
  }
}
